-   subtract      [0] := [1] - [0]          {-1}
*   multiply      [0] := [1] * [0]          {-1}
/   divide        [0] := [1] / [0]          {-1}
%   modulo        [0] := [1] % [0]          {-1}
<   left shift    [0] := [0] << 1           {0}
>   right shift   [0] := [0] >> 1           {0}
++  increment     [0] := [0]++              {0}
--  decrement     [0] := [0]--              {0}
